+/**
+ * Length of `array.join(separator)` for a separator of the given length,
+ * computed without building the string. A nested array stringifies as its
+ * own elements joined by ",", so a few elements can carry far more content
+ * than their count; nullish elements stringify as "". Stops early once past
+ * the cap.
+ */
+function joinedSize(array: unknown[], separatorLength: number): number {
+	let size = separatorLength * Math.max(array.length - 1, 0);
+	for (const element of array) {
+		if (size > MAX_RESULT_LENGTH) break;
+		if (element === null || element === undefined) continue;
+		size += isArray(element) ? joinedSize(element, 1) : toStr(element).length;
+	}
+	return size;
+}
